/*
 * Front-facing head, centred on x=200 in the 400×1000 character space. Light falls from the
 * upper right, so shading sits on the viewer-left side of forms.
 */

const FACE = {
  male: "M152 98 C152 60 172 42 200 42 C228 42 248 60 248 98 C248 112 247 125 244 137 C239 157 225 174 210 180 C204 182 196 182 190 180 C175 174 161 157 156 137 C153 125 152 112 152 98 Z",
  female:
    "M156 98 C156 63 175 46 200 46 C225 46 244 63 244 98 C244 114 242 128 238 140 C232 160 218 173 206 177 C202 178 198 178 194 177 C182 173 168 160 162 140 C158 128 156 114 156 98 Z",
};
const FACE_SHADE = {
  male: "M152 98 C152 122 156 142 167 160 C175 171 184 178 194 181 C181 168 170 150 166 128 C163 112 163 98 168 80 C159 84 152 90 152 98 Z",
  female: "M156 98 C156 122 161 142 170 157 C177 167 185 174 194 177 C183 165 173 149 169 128 C166 112 166 98 170 82 C162 86 156 92 156 98 Z",
};

/** Almond eye with iris, catch-light, lid line; female adds a kohl flick and lashes. */
const Eye: React.FC<{ uid: string; cx: number; cy: number; mirror: boolean; female: boolean; lookX?: number }> = ({
  uid,
  cx,
  cy,
  mirror,
  female,
  lookX = 0,
}) => {
  const w = female ? 25 : 22;
  const h = female ? 9.5 : 8;
  const s = mirror ? -1 : 1;
  const x0 = cx - (w / 2) * s;
  const x1 = cx + (w / 2) * s;
  const shape = `M${x0} ${cy} C${cx - (w / 4) * s} ${cy - h} ${cx + (w / 4) * s} ${cy - h} ${x1} ${cy - 1.5} C${cx + (w / 4) * s} ${cy + h * 0.72} ${cx - (w / 4) * s} ${cy + h * 0.72} ${x0} ${cy} Z`;
  const ir = h * 0.66;
  return (
    <g>
      <path d={shape} fill="#FBF5EC" />
      <clipPath id={`eye-${uid}-${cx}`}>
        <path d={shape} />
      </clipPath>
      <g clipPath={`url(#eye-${uid}-${cx})`}>
        <circle cx={cx + lookX} cy={cy - 0.8} r={ir} fill="#4A2C1C" />
        <circle cx={cx + lookX} cy={cy - 0.8} r={ir * 0.6} fill="#1B0F09" />
        <circle cx={cx + lookX + 2} cy={cy - 3} r={1.6} fill="#FFFFFF" />
        {/* upper-lid shadow */}
        <path d={`M${x0} ${cy} C${cx - (w / 4) * s} ${cy - h} ${cx + (w / 4) * s} ${cy - h} ${x1} ${cy - 1.5} L${x1} ${cy - 10} L${x0} ${cy - 10} Z`} fill="#000" opacity={0.08} />
      </g>
      <path
        d={`M${x0 - 1 * s} ${cy + 0.5} C${cx - (w / 4) * s} ${cy - h - 0.8} ${cx + (w / 4) * s} ${cy - h - 0.8} ${x1 + 1 * s} ${cy - 1.5}`}
        fill="none"
        stroke={palette.ink}
        strokeWidth={female ? 2.6 : 2.1}
        strokeLinecap="round"
      />
      {female ? (
        <>
          <path d={`M${x0 - 1 * s} ${cy + 0.5} L${x0 - 6 * s} ${cy - 3.5}`} stroke={palette.ink} strokeWidth={2.2} strokeLinecap="round" />
          <path d={`M${x0 + 2 * s} ${cy + 2.5} C${cx - 2 * s} ${cy + h * 0.85} ${cx + 5 * s} ${cy + h * 0.7} ${x1} ${cy}`} fill="none" stroke={palette.ink} strokeWidth={0.8} opacity={0.5} />
        </>
      ) : null}
      {/* crease above the lid */}
      <path d={`M${cx - (w / 3) * s} ${cy - h - 3} C${cx} ${cy - h - 5.5} ${cx + (w / 4) * s} ${cy - h - 4.5} ${x1} ${cy - h + 1}`} fill="none" stroke={palette.ink} strokeWidth={0.8} opacity={0.3} />
    </g>
  );
};

const Brow: React.FC<{ cx: number; mirror: boolean; female: boolean; color: string }> = ({ cx, mirror, female, color }) => {
  const s = mirror ? -1 : 1;
  const d = female
    ? `M${cx - 13 * s} ${99} C${cx - 5 * s} ${92} ${cx + 6 * s} ${91} ${cx + 13 * s} ${95} C${cx + 6 * s} ${94} ${cx - 4 * s} ${95} ${cx - 13 * s} ${99} Z`
    : `M${cx - 13 * s} ${98} C${cx - 6 * s} ${91} ${cx + 5 * s} ${90} ${cx + 13 * s} ${93} L${cx + 12 * s} ${97} C${cx + 4 * s} ${95} ${cx - 5 * s} ${96} ${cx - 12 * s} ${101} Z`;
  return <path d={d} fill={color} stroke={color} strokeWidth={female ? 1.2 : 0.6} strokeLinejoin="round" />;
};

