const SPEC_STYLE: Record<Specs, { stroke: string; width: number; rx: number; w: number; h: number }> = {
  roundGold: { stroke: "#B08A45", width: 1.9, rx: 14, w: 28, h: 28 },
  rectDark: { stroke: "#2A1C17", width: 3.2, rx: 4, w: 31, h: 21 },
  matteBlack: { stroke: "#1B1918", width: 3, rx: 8, w: 30, h: 23 },
  roundedSquare: { stroke: "#6A4630", width: 2.8, rx: 9, w: 29, h: 25 },
};

const Spectacles: React.FC<{ kind: Specs }> = ({ kind }) => {
  const s = SPEC_STYLE[kind];
  const lens = (cx: number) => (
    <g>
      <rect x={cx - s.w / 2} y={114 - s.h / 2} width={s.w} height={s.h} rx={s.rx} fill="#FFFFFF" fillOpacity={0.12} stroke={s.stroke} strokeWidth={s.width} />
      <path d={`M${cx - 6} ${114 + 6} L${cx + 4} ${114 - 6}`} stroke="#FFFFFF" strokeWidth={1.6} opacity={0.5} strokeLinecap="round" />
    </g>
  );
  return (
    <g>
      <path d={`M${180 - s.w / 2} 110 L153 104`} stroke={s.stroke} strokeWidth={s.width * 0.75} strokeLinecap="round" />
      <path d={`M${220 + s.w / 2} 110 L247 104`} stroke={s.stroke} strokeWidth={s.width * 0.75} strokeLinecap="round" />
      {lens(180)}
      {lens(220)}
      <path d={`M${180 + s.w / 2} 112 C194 106 206 106 ${220 - s.w / 2} 112`} fill="none" stroke={s.stroke} strokeWidth={s.width * 0.8} />
    </g>
  );
};

const Mouth: React.FC<{ kind: Person["mouth"]; female: boolean; skin: string }> = ({ kind, female, skin }) => {
  if (female) {
    return (
      <g>
        <path d="M187 153 C192 150 196 150.5 200 152 C204 150.5 208 150 213 153 C207 156.5 193 156.5 187 153 Z" fill="#A9464F" />
        <path d="M188 154 C194 161 206 161 212 154 C206 156.5 194 156.5 188 154 Z" fill="#C0606A" />
        <path d="M195 157.5 C198 158.5 202 158.5 205 157.5" stroke="#FFFFFF" strokeWidth={1} opacity={0.35} strokeLinecap="round" />
        {kind !== "softSmile" ? <path d="M186 152 L184 150 M214 152 L216 150" stroke={tone(skin, -0.3)} strokeWidth={1} strokeLinecap="round" /> : null}
      </g>
    );
  }
  if (kind === "grin") {
    return (
      <g>
        <path d="M183 151 C191 165 209 165 217 151 C209 155 191 155 183 151 Z" fill="#FFFDF8" stroke="#7A3A30" strokeWidth={1.6} strokeLinejoin="round" />
        <path d="M188 159 C195 162 205 162 212 159" stroke={tone(skin, -0.25)} strokeWidth={1.2} fill="none" />
      </g>
    );
  }
  return (
    <g>
      <path d="M185 152 C192 158 208 158 215 152" fill="none" stroke="#7E3E34" strokeWidth={2.2} strokeLinecap="round" />
      <path d="M192 160 C197 162 203 162 208 160" fill="none" stroke={tone(skin, -0.2)} strokeWidth={1.4} strokeLinecap="round" />
    </g>
  );
};

export const HeadBack: React.FC<{ p: Person }> = ({ p }) => {
  const hair = HAIR[p.hair];
  return hair.back ? <path d={hair.back} fill={tone(p.hairColor, -0.1)} /> : null;
};

/** Face + features + hair front + specs. `children` renders on top (turban, veil, jewellery). */
export const Head: React.FC<{ p: Person; children?: React.ReactNode; hideHairFront?: boolean }> = ({ p, children, hideHairFront }) => {
  const female = p.face === "female";
  const hair = HAIR[p.hair];
  const shade = tone(p.skin, -0.13);
  return (
    <g>
      {/* ears */}
      <path d="M152 100 C143 97 140 112 142 122 C144 131 151 133 156 128 Z" fill={shade} />
      <path d="M248 100 C257 97 260 112 258 122 C256 131 249 133 244 128 Z" fill={p.skin} />
      <path d="M150 108 C147 112 147 118 150 122" stroke={tone(p.skin, -0.25)} strokeWidth={1.2} fill="none" />
      <path d="M250 108 C253 112 253 118 250 122" stroke={tone(p.skin, -0.2)} strokeWidth={1.2} fill="none" />

      <path d={FACE[p.face]} fill={p.skin} />
      <path d={FACE_SHADE[p.face]} fill={shade} opacity={0.55} />
      {/* cheek warmth */}
      <ellipse cx={173} cy={138} rx={12} ry={7} fill={palette.rose} opacity={female ? 0.2 : 0.1} />
      <ellipse cx={227} cy={138} rx={12} ry={7} fill={palette.rose} opacity={female ? 0.2 : 0.1} />

      {p.beard ? (
        <g fill={p.hairColor}>
          <path d="M154 118 C156 142 166 162 180 174 C187 179 194 182 200 182 C206 182 213 179 220 174 C234 162 244 142 246 118 C242 132 237 141 231 146 C224 151 218 151 213 147 C207 150 193 150 187 147 C182 151 176 151 169 146 C163 141 158 132 154 118 Z" opacity={0.93} />
          <path d="M184 148 C190 142 196 143 200 145.5 C204 143 210 142 216 148 C210 150 204 150.5 200 149.5 C196 150.5 190 150 184 148 Z" />
        </g>
      ) : null}

      {/* nose */}
      <path d="M203 112 C204 124 208 133 206 139 C204 143 198 143 195 140" fill="none" stroke={tone(p.skin, -0.22)} strokeWidth={1.8} strokeLinecap="round" />
      <path d="M190 138 C192 141 194 142 196 141" fill="none" stroke={tone(p.skin, -0.22)} strokeWidth={1.3} strokeLinecap="round" />
      <path d="M197 110 C196 120 195 128 194 134" stroke={shade} strokeWidth={3} opacity={0.35} strokeLinecap="round" />

      <Mouth kind={p.mouth} female={female} skin={p.skin} />

      <Eye uid={p.id} cx={180} cy={114} mirror={false} female={female} />
      <Eye uid={p.id} cx={220} cy={114} mirror female={female} />
      <Brow cx={180} mirror={false} female={female} color={p.hairColor} />
      <Brow cx={220} mirror female={female} color={p.hairColor} />

      {p.bindi ? <circle cx={200} cy={93} r={3.4} fill={palette.maroonLight} /> : null}

      {!hideHairFront ? (
        <g>
          <path d={hair.front} fill={p.hairColor} />
          {p.greyTemples ? (
            <g fill="#A9A29A" opacity={0.85}>
              <path d="M151 106 C150 94 152 84 158 76 C160 88 158 98 156 110 Z" />
              <path d="M249 104 C250 92 248 82 242 74 C240 86 242 96 245 108 Z" />
              <path d="M176 68 C190 60 212 60 228 66 C212 64 192 64 176 68 Z" />
            </g>
          ) : null}
          <g fill="none" stroke="#FFFFFF" strokeWidth={1.4} opacity={0.14} strokeLinecap="round">
            {hair.strands?.map((d, i) => (
              <path key={i} d={d} />
            ))}
          </g>
        </g>
      ) : null}

      {p.specs ? <Spectacles kind={p.specs} /> : null}
      {children}
    </g>
  );
};

